import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const ROOT = process.env.OPENCODE_CONFIG_DIR;
const THREE = await import(pathToFileURL(path.join(ROOT, 'tools/dist-depend/three-bundle.mjs')).href);
const resourceRoot = path.resolve('assets/module/module-realistic-sheep');
const source = fs.readFileSync(path.join(resourceRoot, 'static/preview-module.js'), 'utf8');
const moduleRoot = new THREE.Group();
moduleRoot.name = 'PreviewModuleRoot';
const runtime = { helpers: { clearGroup(g){ if (g && g.children) { for (const c of [...g.children]) g.remove(c); } } }, logger: { info(){}, warn(){}, error(){}, log(){} } };
const factory = new Function('module', 'exports', 'require', source);
const mod = { exports: {} };
factory(mod, mod.exports, (name) => {
  if (name === 'three') return THREE;
  throw new Error('unsupported require ' + name);
});
mod.exports(moduleRoot, runtime);
moduleRoot.updateMatrixWorld(true);
const meshes = [];
moduleRoot.traverse(o => { if (o.isMesh) meshes.push(o); });
console.log('meshes', meshes.length);
const box = new THREE.Box3().setFromObject(moduleRoot);
console.log('bbox size', box.getSize(new THREE.Vector3()).toArray().map(v=>+v.toFixed(3)));
for (const mesh of meshes) {
  const geo = mesh.geometry;
  const pos = geo.attributes.position;
  const index = geo.index;
  const center = new THREE.Vector3();
  const p = new THREE.Vector3();
  for (let i = 0; i < pos.count; i += 1) { p.fromBufferAttribute(pos, i); center.add(p); }
  center.multiplyScalar(1 / pos.count);
  let outward = 0, total = 0;
  const a = new THREE.Vector3(), b = new THREE.Vector3(), c = new THREE.Vector3();
  const ab = new THREE.Vector3(), ac = new THREE.Vector3(), n = new THREE.Vector3(), mid = new THREE.Vector3();
  const triCount = index ? index.count / 3 : pos.count / 3;
  const step = Math.max(1, Math.floor(triCount / 200));
  for (let t = 0; t < triCount; t += step) {
    const i0 = index ? index.getX(t*3) : t*3;
    const i1 = index ? index.getX(t*3+1) : t*3+1;
    const i2 = index ? index.getX(t*3+2) : t*3+2;
    a.fromBufferAttribute(pos, i0); b.fromBufferAttribute(pos, i1); c.fromBufferAttribute(pos, i2);
    ab.subVectors(b, a); ac.subVectors(c, a); n.crossVectors(ab, ac);
    if (n.lengthSq() < 1e-12) continue;
    n.normalize();
    mid.copy(a).add(b).add(c).multiplyScalar(1/3).sub(center).normalize();
    const d = n.dot(mid);
    if (d > 0) outward += 1;
    total += 1;
  }
  const bbox = new THREE.Box3().setFromObject(mesh);
  const size = bbox.getSize(new THREE.Vector3());
  console.log(mesh.name.padEnd(16), 'mat#' + (mesh.material.color ? mesh.material.color.getHexString() : '?'),
    'tris', Math.round(triCount), 'outward', outward + '/' + total,
    'size', size.toArray().map(v=>+v.toFixed(3)).join(','));
}
EOF
